pub use qualia_core_db::{container_10d,render};
#[path="C:/github/qualiaDB/crates/qualia-core-db/src/render/portal/scene_frames.rs"] mod scene_frames;
fn main(){
 let root=std::path::Path::new("C:/github/synth/production/webizen-swarm");let source=root.join(std::env::args().nth(1).unwrap_or("production/aaa-proof/scene-full.json".into()));let scene:serde_json::Value=serde_json::from_slice(&std::fs::read(source).unwrap()).unwrap();let mut records=Vec::new();let mut total=0;
 for a in scene["assets"].as_array().unwrap(){let bytes=std::fs::read(root.join(a["url"].as_str().unwrap().trim_start_matches('/'))).unwrap();let mesh=render::compile_10d::decode_10d_mesh(&bytes).unwrap();let mut uv=vec![[0.;2];mesh.positions.len()];match container_10d::read_texture_coordinate_section_into(&bytes,mesh.positions.len(),&mut uv){Ok(_)|Err(container_10d::TextureCoordinateContainerError::Missing)=>{},Err(e)=>panic!("UV:{e:?}")};let(n,t)=scene_frames::decode_asset_frames(&bytes,&mesh,&uv).unwrap();assert_eq!(n.len(),mesh.positions.len());assert_eq!(t.len(),n.len());assert!(t.iter().all(|t|t.iter().all(|x|x.is_finite())&&t[3].abs()==1.));total+=t.len();records.push(serde_json::json!({"id":a["id"],"source_sha256":a["sha256"],"vertices":t.len(),"passed":true}));}
 assert_eq!(total as u64,scene["vertex_count"].as_u64().unwrap());println!("{}",serde_json::json!({"schema":"webizen.scene-frame-admission/v1","engine":"actual native scene_frames helper + QualiaDB codecs + Etalon UV derivative kernel","merged_vertices":total,"per_asset_scratch_cap":scene_frames::MAX_TANGENT_VERTICES,"assets":records,"gpu_render_test":"pending browser validation"}));
}
